var cache sync.Map // map[string]weak.Pointer[Session]

wp := weak.Make(session)                     // non-owning handle
cache.Store(addr, wp)
runtime.AddCleanup(session, func(k string, wp weak.Pointer[Session]) {
    cache.CompareAndDelete(k, wp)            // weak pointers are comparable
}, addr, wp)

if s := wp.Value(); s != nil {               // promotion may come back nil
    s.RoundTrip()
}
